import React, { useMemo } from 'react';
import { Paragraph } from '../../../typography';
import Styled from './QuantityIndicator.styles';

interface Props {
  total: number;
  currentPage: number;
  numberOfPages: number;
  pageSize: number;
  quantityIndicatorIntl?: string;
}

const QuantityIndicator = ({
  total,
  numberOfPages,
  currentPage,
  pageSize,
  quantityIndicatorIntl = 'of',
}: Props): JSX.Element => {
  const memoizedWidth = useMemo(() => {
    const stringTotalLength = total?.toString()?.length;
    const modifier = (stringTotalLength * 3 + 6) * 8;
    return modifier;
  }, [total]);

  const renderQuantityIndicator = () => {
    const initialRange = pageSize * currentPage - pageSize + 1;
    const finalRange = currentPage === numberOfPages ? total : pageSize * currentPage;
    return `${initialRange} - ${finalRange} ${quantityIndicatorIntl} ${total}`;
  };

  return (
    <Styled.QuantityIndicator css={{ minWidth: `${memoizedWidth}px` }}>
      <Paragraph
        size="basis"
        alignment="right"
        weight="normal"
        colortype="primary"
        foreground="false"
        selectable="true"
      >
        {renderQuantityIndicator()}
      </Paragraph>
    </Styled.QuantityIndicator>
  );
};

export default QuantityIndicator;
